78	/****************************************************************************
79	 * Private Functions - Register Access Helpers
80	 ****************************************************************************/
81	
82	static inline uint32_t getreg32(uintptr_t addr)
83	{
84	  return *(volatile uint32_t *)addr;
85	}
86	
87	static inline void putreg32(uint32_t val, uintptr_t addr)
88	{
89	  *(volatile uint32_t *)addr = val;
90	}
91	
92	static void reset_assert(unsigned int id)
93	{
94	  unsigned int bank = id / 32;
95	  unsigned int bit = id % 32;
96	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
97	
98	  putreg32(reg & ~(1u << bit), REG_RESET_BANK(bank));
99	}
100	
101	static void reset_deassert(unsigned int id)
102	{
103	  unsigned int bank = id / 32;
104	  unsigned int bit = id % 32;
105	  uint32_t reg = getreg32(REG_RESET_BANK(bank));
106	
107	  putreg32(reg | (1u << bit), REG_RESET_BANK(bank));
108	}
109	
110	static void clk_reset_deassert(unsigned int id)
111	{
112	  unsigned int bank = id / 32;
113	  unsigned int bit = id % 32;
114	  uintptr_t addr = SG2000_CLKGEN_BASE + bank * 4;
115	  uint32_t reg = getreg32(addr);
116	
117	  putreg32(reg | (1u << bit), addr);
118	}
