120	/****************************************************************************
121	 * Private Functions - D-Cache Operations (T-Head C906)
122	 *
123	 * The C906 has a 32KB 4-way set-associative D-Cache with 64-byte cache
124	 * lines using PIPT (Physical Index + Physical Tag).  DDR memory
125	 * (0x80000000-0xC0000000) is mapped as cacheable via MMU.  DMA
126	 * descriptors and buffers allocated from the kernel heap are therefore
127	 * cacheable, and explicit cache maintenance is REQUIRED before any DMA
128	 * engine access.
129	 *
130	 * The Synopsys DWMAC DMA engine is NOT cache-coherent on this SoC.
131	 *
132	 * T-Head custom instructions (from CV181x/SG2002 TRM):
133	 *   dcache.cpa  rs1  (0x0295000b)  – Clean (write back) by physical addr
134	 *   dcache.ipa  rs1  (0x02a5000b)  – Invalidate by physical addr
135	 *   dcache.cipa rs1  (0x02b5000b)  – Clean + Invalidate by physical addr
136	 *   sync.s           (0x01b0000b)  – Cache operation sync barrier (NOT standard sync 0x0190000b)
137	 ****************************************************************************/
138	
139	static void dcache_clean_range(uintptr_t start, uintptr_t end)
140	{
141	  register uintptr_t i asm("a0") = start & ~(64 - 1);
142	
143	  for (; i < end; i += 64)
144	    {
145	      asm volatile (".long 0x0295000b" ::: "memory");  /* dcache.cpa a0 */
146	    }
147	
148	  asm volatile (".long 0x01b0000b" ::: "memory");      /* sync.s – T-Head C906 cache sync */
149	}
150	
151	static void dcache_invalidate_range(uintptr_t start, uintptr_t end)
152	{
153	  register uintptr_t i asm("a0") = start & ~(64 - 1);
154	
155	  for (; i < end; i += 64)
156	    {
157	      asm volatile (".long 0x02a5000b" ::: "memory");  /* dcache.ipa a0 */
158	    }
159	
160	  asm volatile (".long 0x01b0000b" ::: "memory");      /* sync.s – T-Head C906 cache sync */
161	}
162	
163	static void dcache_flush_range(uintptr_t start, uintptr_t end)
164	{
165	  register uintptr_t i asm("a0") = start & ~(64 - 1);
166	
167	  for (; i < end; i += 64)
168	    {
169	      asm volatile (".long 0x02b5000b" ::: "memory");  /* dcache.cipa a0 */
170	    }
171	
172	  asm volatile (".long 0x01b0000b" ::: "memory");      /* sync.s – T-Head C906 cache sync */
173	}
