175	/****************************************************************************
176	 * Private Functions - Clock and Reset Control
177	 ****************************************************************************/
178	
179	static void gmac_clock_enable(void)
180	{
181	  uint32_t reg;
182	
183	  /* Enable GMAC0 clocks: clk_500m_eth0 + clk_axi4_eth0 */
184	
185	  reg = getreg32(REG_CLK_EN_0);
186	  reg |= CLK_EN_ETH0_500M | CLK_EN_ETH0_AXI4;
187	  putreg32(reg, REG_CLK_EN_0);
188	
189	  /* Deassert clock-domain resets used by the CVITEK clock-reset
190	   * controller.  Do not confuse these IDs with the main reset-controller
191	   * IDs at 0x03003000.
192	   */
193	
194	  clk_reset_deassert(CLK_RST_500M_ETH0);
195	  clk_reset_deassert(CLK_RST_AXI_ETH0);
196	
197	  /* Release the main reset-controller lines for GMAC and internal EPHY.
198	   * The Linux CVITEK reset driver deasserts by setting the corresponding
199	   * bit in the reset bank.
200	   */
201	
202	  reset_assert(RST_ETH0);
203	  reset_assert(RST_ETHPHY);
204	  reset_assert(RST_ETHPHYRST_APB);
205	  up_udelay(10);
206	  reset_deassert(RST_ETHPHYRST_APB);
207	  reset_deassert(RST_ETHPHY);
208	  reset_deassert(RST_ETH0);
209	  up_udelay(10);
210	
211	  syslog(LOG_INFO, "sg2000_eth: GMAC clocks enabled, CLK_EN_0=0x%08" PRIX32
212	         " RESET0=0x%08" PRIX32 " RESET3=0x%08" PRIX32 "\n",
213	         getreg32(REG_CLK_EN_0), getreg32(REG_RESET_BANK(0)),
214	         getreg32(REG_RESET_BANK(3)));
215	}
