217	/****************************************************************************
218	 * Private Functions - DMA Software Reset
219	 ****************************************************************************/
220	
221	static int dma_soft_reset(uintptr_t gmac_base)
222	{
223	  uint32_t val;
224	  int timeout = 100000;
225	
226	  val = getreg32(gmac_base + DMA_BUS_MODE);
227	  syslog(LOG_INFO, "sg2000_eth: DMA reset begin bus_mode=0x%08" PRIX32
228	         "\n", val);
229	  putreg32(val | DMA_SFT_RESET, gmac_base + DMA_BUS_MODE);
230	
231	  do
232	    {
233	      val = getreg32(gmac_base + DMA_BUS_MODE);
234	      if (!(val & DMA_SFT_RESET))
235	        {
236	          return 0;
237	        }
238	
239	      up_udelay(10);
240	    }
241	  while (--timeout > 0);
242	
243	  syslog(LOG_ERR, "sg2000_eth: DMA reset timeout bus_mode=0x%08" PRIX32
244	         " hw_feature0=0x%08" PRIX32 "\n",
245	         getreg32(gmac_base + DMA_BUS_MODE),
246	         getreg32(gmac_base + GMAC_HW_FEATURE0));
247	  return -1;
248	}
