397	static void ephy_hardware_reset(uintptr_t phy_base, uintptr_t phy_top)
398	{
399	  uint32_t apb_id1;
400	  uint32_t apb_id2;
401	
402	  ephy_led_pinmux();
403	
404	  /* Minimal EPHY init sequence, matches Linux bm_eth_reset_phy() in
405	   * dwmac-cvitek.c and U-Boot cv181x_ephy_id_init() in board.c.
406	   * This ONLY releases resets and programs the PHY ID — it does NOT
407	   * run the full analog tuning sequence.  The full tuning (which
408	   * accesses internal pages and starts auto-negotiation) must run
409	   * AFTER the MDIO interface is confirmed operational, just as
410	   * Linux does in cv182xa_phy_config_init() -> config_init callback.
411	   */
412	
413	  /* Select APB interface to access EPHY registers */
414	
415	  putreg32(0x0001, phy_top + 0x4);
416	
417	  /* Release shutdown */
418	
419	  putreg32(0x0900, phy_top);
420	
421	  /* Release dig_rst_n — enables MII register access via APB */
422	
423	  putreg32(0x0904, phy_top);
424	
425	  /* Switch to Page 5 for ANA init */
426	
427	  putreg32(0x0500, phy_base + 0x7c);
428	
429	  /* ANA_PD (power-down release) */
430	
431	  putreg32(0x0c00, phy_base + 0x40);
432	
433	  /* ANA_EN */
434	
435	  putreg32(0x0c7e, phy_base + 0x40);
436	  up_mdelay(1);
437	
438	  /* Release ana_rst_n */
439	
440	  putreg32(0x0906, phy_top);
441	  putreg32(0x0500, phy_base + 0x7c);
442	
443	  /* Program PHY ID into EPHY registers (so MDIO can discover it) */
444	
445	  putreg32(0x0043, phy_base + 0x08);  /* PHY_ID_HIGH */
446	  putreg32(0x5649, phy_base + 0x0c);  /* PHY_ID_LOW */
447	
448	  apb_id1 = getreg32(phy_base + 0x08) & 0xffff;
449	  apb_id2 = getreg32(phy_base + 0x0c) & 0xffff;
450	  syslog(LOG_INFO, "sg2000_eth: EPHY APB PHYID=0x%04" PRIX32
451	         "%04" PRIX32 "\n", apb_id1, apb_id2);
452	
453	  /* Switch control to MDIO (GMAC) so the DWMAC4 MDIO controller can
454	   * discover and communicate with the PHY.
455	   */
456	
457	  putreg32(0x0000, phy_top + 0x4);
458	  up_mdelay(10);
459	
460	  syslog(LOG_INFO, "sg2000_eth: EPHY init done top=0x%08" PRIX32
461	         " sel=0x%08" PRIX32 "\n",
462	         getreg32(phy_top), getreg32(phy_top + 0x4));
463	}
