465	/****************************************************************************
466	 * Name: ephy_full_tuning
467	 *
468	 * Description:
469	 *   Run the full CV182XA analog tuning sequence via APB, then switch back
470	 *   to MDIO control.  Matches Linux cv182xa_phy_config_init().
471	 *   MUST be called AFTER MDIO is confirmed operational, as it accesses
472	 *   internal pages and starts auto-negotiation which can interfere with
473	 *   MDIO if run before the MDIO interface is active.
474	 *
475	 ****************************************************************************/
476	
477	static void ephy_full_tuning(uintptr_t phy_base, uintptr_t phy_top)
478	{
479	  /* ephy_full_analog_init expects APB mode; caller ensures MDIO is working
480	   * before we switch to APB for tuning.
481	   */
482	
483	  putreg32(0x0001, phy_top + 0x4);
484	  ephy_full_analog_init(phy_base, phy_top);
485	
486	  /* ephy_full_analog_init ends with:
487	   *   page 0 + autoneg start (0x090e) + force full-duplex
488	   * Switch control back to MDIO so the GMAC can manage the PHY.
489	   */
490	
491	  putreg32(0x0000, phy_top + 0x4);
492	  up_mdelay(10);
493	
494	  syslog(LOG_INFO, "sg2000_eth: EPHY full tuning done, top=0x%08" PRIX32
495	         " sel=0x%08" PRIX32 "\n",
496	         getreg32(phy_top), getreg32(phy_top + 0x4));
497	}
