499	/* SG2000/CV181x uses the TRM (Technical Reference Manual) Chapter 18
500	 * legacy GMAC MDIO layout at offsets 0x10/0x14.  The standard DWMAC4
501	 * MDIO controller at 0x200/0x204 is not functional on this silicon.
502	 */
503	
504	static uint16_t mdio_read(uintptr_t gmac_base, int phy_addr, int reg)
505	{
506	  uint32_t cmd;
507	  int timeout = 10000;
508	
509	  do
510	    {
511	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
512	            LEGACY_GMAC_MDIO_BUSY))
513	        {
514	          break;
515	        }
516	
517	      up_udelay(1);
518	    }
519	  while (--timeout > 0);
520	
521	  if (timeout <= 0)
522	    {
523	      return 0xffff;
524	    }
525	
526	  putreg32(0, gmac_base + LEGACY_GMAC_MDIO_DATA);
527	
528	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
529	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
530	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_BUSY;
531	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
532	
533	  timeout = 10000;
534	  do
535	    {
536	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
537	            LEGACY_GMAC_MDIO_BUSY))
538	        {
539	          return getreg32(gmac_base + LEGACY_GMAC_MDIO_DATA) & 0xffff;
540	        }
541	
542	      up_udelay(1);
543	    }
544	  while (--timeout > 0);
545	
546	  return 0xffff;
547	}
548	
549	static void mdio_write(uintptr_t gmac_base, int phy_addr, int reg,
550	                       uint16_t data)
551	{
552	  uint32_t cmd;
553	  int timeout = 10000;
554	
555	  putreg32(data, gmac_base + LEGACY_GMAC_MDIO_DATA);
556	  cmd = (((uint32_t)phy_addr & 0x1f) << LEGACY_GMAC_MDIO_PHY_SHIFT) |
557	        (((uint32_t)reg & 0x1f) << LEGACY_GMAC_MDIO_REG_SHIFT) |
558	        LEGACY_GMAC_MDIO_CR_250_300M | LEGACY_GMAC_MDIO_WRITE |
559	        LEGACY_GMAC_MDIO_BUSY;
560	  putreg32(cmd, gmac_base + LEGACY_GMAC_MDIO_ADDR);
561	
562	  do
563	    {
564	      if (!(getreg32(gmac_base + LEGACY_GMAC_MDIO_ADDR) &
565	            LEGACY_GMAC_MDIO_BUSY))
566	        {
567	          break;
568	        }
569	
570	      up_udelay(1);
571	    }
572	  while (--timeout > 0);
573	}
574	
575	static int mdio_verify_phy(uintptr_t gmac_base)
576	{
577	  uint16_t id1 = mdio_read(gmac_base, 0, 2);
578	  uint16_t id2 = mdio_read(gmac_base, 0, 3);
579	  uint32_t phy_id = ((uint32_t)id1 << 16) | id2;
580	
581	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO probe phy_id=0x%08"
582	         PRIX32 "\n", phy_id);
583	
584	  if (id1 == 0xffff || id2 == 0xffff)
585	    {
586	      syslog(LOG_ERR, "sg2000_eth: TRM legacy MDIO timeout reading "
587	             "PHY ID\n");
588	      return -ENODEV;
589	    }
590	
591	  if (phy_id != CVITEK_PHY_ID)
592	    {
593	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
594	             " (expected 0x%08" PRIX32 ")\n", phy_id,
595	             (uint32_t)CVITEK_PHY_ID);
596	    }
597	
598	  return OK;
599	}
