601	/****************************************************************************
602	 * Private Functions - PHY Configuration
603	 ****************************************************************************/
604	
605	static int phy_config_init(struct sg2000_eth_priv_s *priv)
606	{
607	  uint16_t bmsr;
608	  uint16_t bmcr;
609	  uint16_t anlpar;
610	  int timeout;
611	  uint16_t id1 = mdio_read(priv->gmac_base, 0, 2);
612	  uint16_t id2 = mdio_read(priv->gmac_base, 0, 3);
613	  uint32_t phy_id = (id1 << 16) | id2;
614	
615	  syslog(LOG_INFO, "sg2000_eth: PHY ID=0x%08" PRIX32
616	         " expect=0x00435649\n", phy_id);
617	
618	  if (phy_id == 0xffffffff)
619	    {
620	      syslog(LOG_ERR, "sg2000_eth: PHY not responding\n");
621	      return -1;
622	    }
623	
624	  if (phy_id != CVITEK_PHY_ID)
625	    {
626	      syslog(LOG_WARNING, "sg2000_eth: unexpected PHY ID 0x%08" PRIX32
627	             "\n", phy_id);
628	    }
629	
630	  priv->speed = 100;
631	  priv->duplex = 1;
632	
633	  mdio_write(priv->gmac_base, 0, 0, 0x8000);
634	  up_mdelay(10);
635	
636	  timeout = 100;
637	  do
638	    {
639	      bmcr = mdio_read(priv->gmac_base, 0, 0);
640	      if (!(bmcr & 0x8000))
641	        {
642	          break;
643	        }
644	
645	      up_mdelay(1);
646	    }
647	  while (--timeout > 0);
648	
649	  syslog(LOG_INFO, "sg2000_eth: PHY reset done, BMCR=0x%04X\n", bmcr);
650	
651	  mdio_write(priv->gmac_base, 0, 4, 0x01e1);
652	
653	  bmcr = mdio_read(priv->gmac_base, 0, 0);
654	  mdio_write(priv->gmac_base, 0, 0, bmcr | 0x1200);
655	  syslog(LOG_INFO, "sg2000_eth: autoneg start, BMCR=0x%04X\n",
656	         bmcr | 0x1200);
657	
658	  timeout = 50;
659	  do
660	    {
661	      (void)mdio_read(priv->gmac_base, 0, 1);
662	      bmsr = mdio_read(priv->gmac_base, 0, 1);
663	      if ((bmsr & 0x0004) != 0)
664	        {
665	          break;
666	        }
667	
668	      up_mdelay(100);
669	    }
670	  while (--timeout > 0);
671	
672	  if ((bmsr & 0x0004) == 0)
673	    {
674	      syslog(LOG_WARNING, "sg2000_eth: PHY link down, BMSR=0x%04X\n",
675	             bmsr);
676	      priv->link_up = 0;
677	      return OK;
678	    }
679	
680	  anlpar = mdio_read(priv->gmac_base, 0, 5);
681	  syslog(LOG_INFO, "sg2000_eth: PHY link detected, BMSR=0x%04X "
682	         "ANLPAR=0x%04X\n", bmsr, anlpar);
683	
684	  if ((anlpar & 0x0100) != 0)
685	    {
686	      priv->speed = 100;
687	      priv->duplex = 1;
688	    }
689	  else if ((anlpar & 0x0080) != 0)
690	    {
691	      priv->speed = 100;
692	      priv->duplex = 0;
693	    }
694	  else if ((anlpar & 0x0040) != 0)
695	    {
696	      priv->speed = 10;
697	      priv->duplex = 1;
698	    }
699	  else
700	    {
701	      priv->speed = 10;
702	      priv->duplex = 0;
703	    }
704	
705	  priv->link_up = 1;
706	
707	  return 0;
708	}
709	
710	/****************************************************************************
711	 * Private Functions - DMA Descriptor Management
712	 ****************************************************************************/
713	
714	static int alloc_dma(struct sg2000_eth_priv_s *priv)
715	{
716	  int i;
717	
718	  /* Descriptors and buffers MUST be aligned to the C906 cache-line
719	   * size (64 bytes, ARCH_DMA_MINALIGN) to prevent cache-line sharing
720	   * between adjacent descriptors/buffers, which would cause data
721	   * corruption when CPU and DMA write to different entities that
722	   * share the same cache line.
723	   */
724	
725	  priv->tx_desc = kmm_memalign(64, TX_RING_SIZE *
726	                                sizeof(struct sg2000_dma_desc_s));
727	  priv->rx_desc = kmm_memalign(64, RX_RING_SIZE *
728	                                sizeof(struct sg2000_dma_desc_s));
729	
730	  if (!priv->tx_desc || !priv->rx_desc)
731	    {
732	      return -ENOMEM;
733	    }
734	
735	  memset(priv->tx_desc, 0, TX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
736	  memset(priv->rx_desc, 0, RX_RING_SIZE * sizeof(struct sg2000_dma_desc_s));
737	
738	  /* For MMU-less or identity-mapped platforms, virtual address = physical.
739	   * TODO: For strict MMU kernel builds, use mm_virt_to_phys().
740	   */
741	
742	  priv->tx_desc_phys = (uint32_t)(uintptr_t)priv->tx_desc;
743	  priv->rx_desc_phys = (uint32_t)(uintptr_t)priv->rx_desc;
744	
745	  for (i = 0; i < TX_RING_SIZE; i++)
746	    {
747	      priv->tx_buf[i] = kmm_memalign(64, TX_BUF_SIZE);
748	      if (!priv->tx_buf[i])
749	        {
750	          return -ENOMEM;
751	        }
752	
753	      priv->tx_pkt[i] = NULL;
754	    }
755	
756	  for (i = 0; i < RX_RING_SIZE; i++)
757	    {
758	      priv->rx_buf[i] = kmm_memalign(64, RX_BUF_SIZE);
759	      if (!priv->rx_buf[i])
760	        {
761	          return -ENOMEM;
762	        }
763	    }
764	
765	  return 0;
766	}
767	
768	static void init_desc_and_dma(struct sg2000_eth_priv_s *priv)
769	{
770	  uintptr_t base = priv->gmac_base;
771	  int i;
772	  int last;
773	
774	  /* Program DMA Bus Mode register with operational parameters.
775	   * After dma_soft_reset() all bits are cleared; PBL (burst length)
776	   * MUST be programmed for DMA transfers to work.  Use PBL=8
777	   * matching the device tree snps,txpbl/snps,rxpbl settings.
778	   * ATDS=0 selects 16-byte descriptors.
779	   */
780	
781	  putreg32(DMA_PBL_8 | DMA_FB | DMA_AAL, base + DMA_BUS_MODE);
782	
783	  /* Initialize TX descriptors.  The last descriptor has TER (End of Ring)
784	   * set so DWMAC1000 wraps back to the ring base address.
785	   */
786	
787	  last = TX_RING_SIZE - 1;
788	  for (i = 0; i < TX_RING_SIZE; i++)
789	    {
790	      priv->tx_desc[i].des0 = (i == last) ? TX_DESC_TER : 0;
791	      priv->tx_desc[i].des1 = 0;
792	      priv->tx_desc[i].des2 = (uint32_t)(uintptr_t)priv->tx_buf[i];
793	      priv->tx_desc[i].des3 = 0;
794	      priv->tx_pkt[i] = NULL;
795	    }
796	
797	  /* Flush TX descriptor ring so DMA sees the initialized state */
798	
799	  dcache_clean_range((uintptr_t)priv->tx_desc,
800	                     (uintptr_t)(priv->tx_desc + TX_RING_SIZE));
801	
802	  /* Initialize RX descriptors: set OWN=1 (DMA owns them, can write).
803	   * The last descriptor has RER (End of Ring) set so DWMAC1000 wraps.
804	   */
805	
806	  last = RX_RING_SIZE - 1;
807	  for (i = 0; i < RX_RING_SIZE; i++)
808	    {
809	      priv->rx_desc[i].des0 = DESC_OWN | ((i == last) ? RX_DESC_RER : 0);
810	      priv->rx_desc[i].des1 = RX_BUF_SIZE;
811	      priv->rx_desc[i].des2 = (uint32_t)(uintptr_t)priv->rx_buf[i];
812	      priv->rx_desc[i].des3 = 0;
813	    }
814	
815	  /* Flush RX descriptor ring and buffers: DMA will read descriptors
816	   * and write data into the buffers.  Write back the descriptors so
817	   * DMA sees OWN=1.  Also flush RX buffers to ensure any stale cache
818	   * lines are written back before DMA overwrites them.
819	   */
820	
821	  dcache_clean_range((uintptr_t)priv->rx_desc,
822	                     (uintptr_t)(priv->rx_desc + RX_RING_SIZE));
823	
824	  for (i = 0; i < RX_RING_SIZE; i++)
825	    {
826	      dcache_flush_range((uintptr_t)priv->rx_buf[i],
827	                         (uintptr_t)priv->rx_buf[i] + RX_BUF_SIZE);
828	    }
829	
830	  priv->tx_cur = 0;
831	  priv->tx_dirty = 0;
832	  priv->rx_cur = 0;
833	
834	  /* Program DWMAC1000 flat DMA registers.
835	   * DWMAC1000 has NO ring-length registers; wrapping uses TER/RER bits.
836	   * DWMAC1000 has NO channel concept; all registers are flat at 0x1000+.
837	   */
838	
839	  putreg32(priv->tx_desc_phys, base + DMA_TX_BASE_ADDR);
840	  putreg32(priv->rx_desc_phys, base + DMA_RCV_BASE_ADDR);
841	
842	  /* Clear any pending interrupts before enabling them */
843	
844	  putreg32(0x1ffff, base + DMA_STATUS);
845	  putreg32(DMA_INTR_DEFAULT_MASK, base + DMA_INTR_ENA);
846	
847	  syslog(LOG_INFO, "sg2000_eth: DMA init done "
848	         "tx_desc=0x%08" PRIX32 " rx_desc=0x%08" PRIX32
849	         " tx_buf0=0x%08" PRIX32 " rx_buf0=0x%08" PRIX32 "\n",
850	         priv->tx_desc_phys, priv->rx_desc_phys,
851	         (uint32_t)(uintptr_t)priv->tx_buf[0],
852	         (uint32_t)(uintptr_t)priv->rx_buf[0]);
853	}
854	
855	/****************************************************************************
856	 * Private Functions - MAC and DMA Control
857	 ****************************************************************************/
858	
859	static void set_mac_addr(uintptr_t gmac_base, const uint8_t *mac)
860	{
861	  uint32_t hi;
862	  uint32_t lo;
863	
864	  hi = (mac[5] << 8) | mac[4] | GMAC_HI_REG_AE;
865	  lo = (mac[3] << 24) | (mac[2] << 16) | (mac[1] << 8) | mac[0];
866	
867	  putreg32(hi, gmac_base + GMAC_ADDR_HIGH(0));
868	  putreg32(lo, gmac_base + GMAC_ADDR_LOW(0));
869	}
870	
871	static void start_mac_and_dma(struct sg2000_eth_priv_s *priv)
872	{
873	  uintptr_t gmac_base = priv->gmac_base;
874	  uint32_t v;
875	
876	  /* Configure MAC based on PHY negotiation results */
877	
878	  v = GMAC_CORE_INIT;
879	  if (priv->speed == 100)
880	    {
881	      v |= GMAC_CONFIG_FES;   /* 100M */
882	    }
883	
884	  if (priv->duplex)
885	    {
886	      v |= GMAC_CONFIG_DM;    /* Full duplex */
887	    }
888	
889	  putreg32(v, gmac_base + GMAC_CONFIG);
890	
891	  /* Packet filter: pass multicast + broadcast + unicast to us */
892	
893	  putreg32(GMAC_FILTER_HMC | GMAC_FILTER_PM | GMAC_FILTER_PR,
894	           gmac_base + GMAC_PACKET_FILTER);
895	
896	  /* Clear any pending MAC interrupts */
897	
898	  putreg32(0xffffffff, gmac_base + GMAC_INT_STATUS);
899	
900	  /* Enable MAC interrupts */
901	
902	  putreg32(GMAC_INT_DEFAULT, gmac_base + GMAC_INT_EN);
903	
904	  /* Flush TX and RX FIFOs before enabling MAC/DMA */
905	
906	  putreg32(0, gmac_base + 0x0048);  /* GMAC_TX_FLUSH */
907	  putreg32(0, gmac_base + 0x004c);  /* GMAC_RX_FLUSH */
908	
909	  /* Enable MAC TX and RX */
910	
911	  v = getreg32(gmac_base + GMAC_CONFIG);
912	  putreg32(v | GMAC_CONFIG_TE | GMAC_CONFIG_RE, gmac_base + GMAC_CONFIG);
913	
914	  /* Start TX DMA via DWMAC1000 DMA_CONTROL (CSR6, 0x1018).
915	   * Bit 13 = ST (Start Transmit), Bit 0 = SR (Start Receive).
916	   * Start TX first; RX will be started after a short delay to avoid
917	   * race conditions where RX DMA tries to use descriptors before
918	   * the TX path is fully ready.
919	   */
920	
921	  v = getreg32(gmac_base + DMA_CONTROL);
922	  putreg32(v | DMA_CONTROL_ST, gmac_base + DMA_CONTROL);
923	  up_udelay(10);
924	
925	  v = getreg32(gmac_base + DMA_CONTROL);
926	  putreg32(v | DMA_CONTROL_SR, gmac_base + DMA_CONTROL);
927	
928	  syslog(LOG_INFO, "sg2000_eth: DMA started "
929	         "bus_mode=0x%08" PRIX32 " dma_control=0x%08" PRIX32
930	         " dma_status=0x%08" PRIX32 " dma_intr=0x%08" PRIX32
931	         " tx_base=0x%08" PRIX32 " rx_base=0x%08" PRIX32 "\n",
932	         getreg32(gmac_base + DMA_BUS_MODE),
933	         getreg32(gmac_base + DMA_CONTROL),
934	         getreg32(gmac_base + DMA_STATUS),
935	         getreg32(gmac_base + DMA_INTR_ENA),
936	         getreg32(gmac_base + DMA_TX_BASE_ADDR),
937	         getreg32(gmac_base + DMA_RCV_BASE_ADDR));
938	}
