940	/****************************************************************************
941	 * Private Functions - Doorbell Helpers
942	 ****************************************************************************/
943	
944	static void tx_doorbell(struct sg2000_eth_priv_s *priv)
945	{
946	  /* DWMAC1000: writing ANY value to DMA_XMT_POLL_DEMAND (0x1004)
947	   * triggers the DMA to re-fetch TX descriptors from the ring.
948	   */
949	
950	  putreg32(0, priv->gmac_base + DMA_XMT_POLL_DEMAND);
951	}
952	
953	static void rx_doorbell(struct sg2000_eth_priv_s *priv)
954	{
955	  /* DWMAC1000: writing ANY value to DMA_RCV_POLL_DEMAND (0x1008)
956	   * triggers the DMA to re-fetch RX descriptors from the ring.
957	   */
958	
959	  putreg32(0, priv->gmac_base + DMA_RCV_POLL_DEMAND);
960	}
961	
962	/****************************************************************************
963	 * Private Functions - Hardware Transmit
964	 ****************************************************************************/
965	
966	static int hw_transmit(struct sg2000_eth_priv_s *priv,
967	                       const uint8_t *data, int len)
968	{
969	  unsigned int idx = priv->tx_cur;
970	  struct sg2000_dma_desc_s *desc = &priv->tx_desc[idx];
971	  irqstate_t flags;
972	
973	  /* Check if the ring is full */
974	
975	  if (desc->des0 & DESC_OWN)
976	    {
977	      return -EBUSY;
978	    }
979	
980	  /* Copy data to DMA TX buffer */
981	
982	  memcpy(priv->tx_buf[idx], data, len);
983	
984	  /* Write back the TX buffer so DMA can see the packet data.
985	   * Without this, the CPU's cache may hold dirty lines that the
986	   * non-coherent DMA engine cannot see.
987	   */
988	
989	  dcache_clean_range((uintptr_t)priv->tx_buf[idx],
990	                     (uintptr_t)priv->tx_buf[idx] + len);
991	
992	  desc->des2 = (uint32_t)(uintptr_t)priv->tx_buf[idx];
993	  desc->des1 = len;
994	
995	  /* OWN | First Segment | Last Segment | Interrupt on Completion.
996	   * Preserve TER (End of Ring) bit for the last descriptor so the
997	   * DWMAC1000 DMA engine wraps back to the ring base address.
998	   */
999	
1000	  desc->des0 = DESC_OWN | TX_DESC_FS | TX_DESC_LS | TX_DESC_IC |
1001	               ((idx == (TX_RING_SIZE - 1)) ? TX_DESC_TER : 0) |
1002	               (len & RX_DESC_FL_MASK);
1003	
1004	  /* Write back the descriptor so DMA sees OWN=1 and the buffer address.
1005	   * The fence ensures the stores are ordered before the doorbell write.
1006	   */
1007	
1008	  dcache_clean_range((uintptr_t)desc,
1009	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1010	  __asm__ volatile ("fence w,w" ::: "memory");
1011	
1012	  flags = up_irq_save();
1013	  priv->tx_cur = (idx + 1) & (TX_RING_SIZE - 1);
1014	  tx_doorbell(priv);
1015	  up_irq_restore(flags);
1016	
1017	  syslog(LOG_INFO, "sg2000_eth: TX %u bytes, desc[%u] des0=0x%08" PRIX32
1018	         " des1=0x%08" PRIX32 " des2=0x%08" PRIX32
1019	         " dma_status=0x%08" PRIX32 "\n",
1020	         len, idx, desc->des0, desc->des1, desc->des2,
1021	         getreg32(priv->gmac_base + DMA_STATUS));
1022	
1023	  return 0;
1024	}
1025	
1026	/****************************************************************************
1027	 * Private Functions - TX Cleanup (called from ISR on TX complete)
1028	 ****************************************************************************/
1029	
1030	static void tx_cleanup(struct sg2000_eth_priv_s *priv)
1031	{
1032	  irqstate_t flags = up_irq_save();
1033	
1034	  while (priv->tx_dirty != priv->tx_cur)
1035	    {
1036	      struct sg2000_dma_desc_s *desc = &priv->tx_desc[priv->tx_dirty];
1037	
1038	      /* Invalidate the descriptor cache line so we read the status
1039	       * that DMA wrote back, not stale cached data.
1040	       */
1041	
1042	      dcache_invalidate_range((uintptr_t)desc,
1043	                              (uintptr_t)desc +
1044	                              sizeof(struct sg2000_dma_desc_s));
1045	
1046	      if (desc->des0 & DESC_OWN)
1047	        {
1048	          /* Still owned by DMA, stop */
1049	
1050	          break;
1051	        }
1052	
1053	      /* Check for TX errors */
1054	
1055	      if (desc->des0 & TX_DESC_ES)
1056	        {
1057	          nerr("ERROR: TX error, status=0x%08" PRIX32 "\n", desc->des0);
1058	        }
1059	
1060	      /* Free the netpkt if we have one tracked for this slot */
1061	
1062	      if (priv->tx_pkt[priv->tx_dirty] != NULL)
1063	        {
1064	          netpkt_free(&priv->dev, priv->tx_pkt[priv->tx_dirty], NETPKT_TX);
1065	          priv->tx_pkt[priv->tx_dirty] = NULL;
1066	
1067	          /* Notify upper half that TX is done */
1068	
1069	          netdev_lower_txdone(&priv->dev);
1070	        }
1071	
1072	      /* Release descriptor: clear des0 so it can be reused. */
1073	
1074	      desc->des0 = 0;
1075	
1076	      /* Write back the cleared descriptor so DMA doesn't see stale OWN */
1077	
1078	      dcache_clean_range((uintptr_t)desc,
1079	                         (uintptr_t)desc +
1080	                         sizeof(struct sg2000_dma_desc_s));
1081	
1082	      /* Move to next descriptor */
1083	
1084	      priv->tx_dirty = (priv->tx_dirty + 1) & (TX_RING_SIZE - 1);
1085	    }
1086	
1087	  up_irq_restore(flags);
1088	}
1089	
1090	/****************************************************************************
1091	 * Private Functions - ISR
1092	 ****************************************************************************/
1093	
1094	static int sg2000_eth_isr(int irq, void *context, void *arg)
1095	{
1096	  struct sg2000_eth_priv_s *priv = (struct sg2000_eth_priv_s *)arg;
1097	  uintptr_t base = priv->gmac_base;
1098	  uint32_t status;
1099	  uint32_t intr_en;
1100	  uint32_t mac;
1101	
1102	  /* Clear MAC interrupts */
1103	
1104	  mac = getreg32(base + GMAC_INT_STATUS);
1105	  if (mac)
1106	    {
1107	      putreg32(mac, base + GMAC_INT_STATUS);
1108	    }
1109	
1110	  /* Read DWMAC1000 DMA Status (CSR5, 0x1014) masked by enabled interrupts */
1111	
1112	  intr_en = getreg32(base + DMA_INTR_ENA);
1113	  status = getreg32(base + DMA_STATUS) & intr_en;
1114	
1115	  if (status & (DMA_STATUS_TI | DMA_STATUS_RI | DMA_STATUS_NIS |
1116	                DMA_STATUS_AIS | DMA_STATUS_FBI | DMA_STATUS_TPS |
1117	                DMA_STATUS_RPS | DMA_STATUS_RBU))
1118	    {
1119	      syslog(LOG_INFO, "sg2000_eth: ISR dma_status=0x%08" PRIX32
1120	             " intr_en=0x%08" PRIX32 " mac_int=0x%08" PRIX32 "\n",
1121	             getreg32(base + DMA_STATUS), intr_en, mac);
1122	    }
1123	
1124	  if (!status)
1125	    {
1126	      return OK;
1127	    }
1128	
1129	  /* Write-1-to-clear the status bits */
1130	
1131	  putreg32(status, base + DMA_STATUS);
1132	
1133	  if (status & DMA_STATUS_NIS)
1134	    {
1135	      /* Normal interrupt */
1136	
1137	      if (status & DMA_STATUS_RI)
1138	        {
1139	          /* RX complete: notify upper half that packets are ready.
1140	           * The upper half will call our receive() callback to get them.
1141	           */
1142	
1143	          netdev_lower_rxready(&priv->dev);
1144	        }
1145	
1146	      if (status & DMA_STATUS_TI)
1147	        {
1148	          /* TX complete: cleanup descriptors and notify upper half */
1149	
1150	          tx_cleanup(priv);
1151	        }
1152	    }
1153	
1154	  if (status & DMA_STATUS_AIS)
1155	    {
1156	      /* Abnormal interrupt */
1157	
1158	      nerr("ERROR: DMA Abnormal: 0x%08" PRIX32 "\n", status);
1159	
1160	      if (status & DMA_STATUS_RBU)
1161	        {
1162	          nerr("ERROR: RX Buffer Unavailable\n");
1163	        }
1164	
1165	      if (status & DMA_STATUS_TPS)
1166	        {
1167	          nerr("ERROR: TX Process Stopped\n");
1168	        }
1169	
1170	      if (status & DMA_STATUS_FBI)
1171	        {
1172	          nerr("ERROR: Fatal Bus Error\n");
1173	        }
1174	    }
1175	
1176	  return OK;
1177	}
