1179	/****************************************************************************
1180	 * Name: netdriver_ifup
1181	 *
1182	 * Description:
1183	 *   OpenVela netdev_ops_s ifup callback.  Starts the network device.
1184	 *
1185	 ****************************************************************************/
1186	
1187	static int netdriver_ifup(FAR struct netdev_lowerhalf_s *dev)
1188	{
1189	  FAR struct sg2000_eth_priv_s *priv =
1190	      (FAR struct sg2000_eth_priv_s *)dev;
1191	  int ret;
1192	
1193	  syslog(LOG_INFO, "sg2000_eth: ifup begin\n");
1194	
1195	  /* Ensure GMAC clocks and resets are configured */
1196	
1197	  gmac_clock_enable();
1198	
1199	  /* Set MAC core init (includes PS=MII mode) before PHY/MDIO operations. */
1200	
1201	  putreg32(GMAC_CORE_INIT, priv->gmac_base + GMAC_CONFIG);
1202	
1203	  ephy_hardware_reset(priv->phy_base, priv->phy_top);
1204	  up_mdelay(10);
1205	
1206	  ret = mdio_verify_phy(priv->gmac_base);
1207	  if (ret < 0)
1208	    {
1209	      nerr("ERROR: TRM legacy MDIO PHY not responding: %d\n", ret);
1210	      return ret;
1211	    }
1212	
1213	  syslog(LOG_INFO, "sg2000_eth: TRM legacy MDIO operational "
1214	         "mdio_addr=0x%08" PRIX32 " mdio_data=0x%08" PRIX32 "\n",
1215	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_ADDR),
1216	         getreg32(priv->gmac_base + LEGACY_GMAC_MDIO_DATA));
1217	
1218	  ephy_full_tuning(priv->phy_base, priv->phy_top);
1219	
1220	  ret = phy_config_init(priv);
1221	  if (ret < 0)
1222	    {
1223	      nerr("ERROR: PHY init failed: %d\n", ret);
1224	      return ret;
1225	    }
1226	
1227	  ret = dma_soft_reset(priv->gmac_base);
1228	  if (ret < 0)
1229	    {
1230	      syslog(LOG_ERR, "sg2000_eth: DMA reset failed after PHY/MDIO "
1231	             "diagnostics: %d\n", ret);
1232	      return ret;
1233	    }
1234	
1235	  if (priv->tx_desc == NULL || priv->rx_desc == NULL)
1236	    {
1237	      ret = alloc_dma(priv);
1238	      if (ret < 0)
1239	        {
1240	          nerr("ERROR: alloc_dma failed: %d\n", ret);
1241	          return ret;
1242	        }
1243	    }
1244	
1245	  init_desc_and_dma(priv);
1246	  set_mac_addr(priv->gmac_base, priv->mac_addr);
1247	  start_mac_and_dma(priv);
1248	  rx_doorbell(priv);
1249	
1250	  up_enable_irq(priv->irq);
1251	  netdev_lower_carrier_on(dev);
1252	
1253	  syslog(LOG_INFO, "sg2000_eth: ifup done, %d Mbps %s duplex\n",
1254	         priv->speed, priv->duplex ? "Full" : "Half");
1255	
1256	  return OK;
1257	}
