1259	/****************************************************************************
1260	 * Name: netdriver_ifdown
1261	 *
1262	 * Description:
1263	 *   OpenVela netdev_ops_s ifdown callback.  Stops the network device.
1264	 *
1265	 ****************************************************************************/
1266	
1267	static int netdriver_ifdown(FAR struct netdev_lowerhalf_s *dev)
1268	{
1269	  FAR struct sg2000_eth_priv_s *priv =
1270	      (FAR struct sg2000_eth_priv_s *)dev;
1271	  uint32_t v;
1272	
1273	  up_disable_irq(priv->irq);
1274	
1275	  /* Stop TX and RX DMA via DWMAC1000 DMA_CONTROL (CSR6, 0x1018).
1276	   * Bit 13 = ST (Start Transmit), Bit 0 = SR (Start Receive).
1277	   */
1278	
1279	  v = getreg32(priv->gmac_base + DMA_CONTROL);
1280	  putreg32(v & ~(DMA_CONTROL_ST | DMA_CONTROL_SR),
1281	           priv->gmac_base + DMA_CONTROL);
1282	
1283	  /* Disable MAC TX/RX */
1284	
1285	  v = getreg32(priv->gmac_base + GMAC_CONFIG);
1286	  putreg32(v & ~(GMAC_CONFIG_TE | GMAC_CONFIG_RE),
1287	           priv->gmac_base + GMAC_CONFIG);
1288	
1289	  netdev_lower_carrier_off(dev);
1290	
1291	  ninfo("netdriver_ifdown: interface down\n");
1292	
1293	  return OK;
1294	}
