1296	/****************************************************************************
1297	 * Name: netdriver_transmit
1298	 *
1299	 * Description:
1300	 *   OpenVela netdev_ops_s transmit callback.  Sends a packet.
1301	 *   The driver takes ownership of the netpkt and MUST free it after TX
1302	 *   completion (or on error).
1303	 *
1304	 *   Returned Value:
1305	 *     OK on success (pkt queued for TX); negated errno on failure.
1306	 *
1307	 ****************************************************************************/
1308	
1309	static int netdriver_transmit(FAR struct netdev_lowerhalf_s *dev,
1310	                               FAR netpkt_t *pkt)
1311	{
1312	  FAR struct sg2000_eth_priv_s *priv =
1313	      (FAR struct sg2000_eth_priv_s *)dev;
1314	  unsigned int len = netpkt_getdatalen(dev, pkt);
1315	  uint8_t tmp_buf[SG2000_ETH_BUFSIZE];
1316	  const uint8_t *data;
1317	  int ret;
1318	
1319	  if (len > SG2000_ETH_BUFSIZE)
1320	    {
1321	      nerr("ERROR: TX packet too large: %u\n", len);
1322	      netpkt_free(dev, pkt, NETPKT_TX);
1323	      return -E2BIG;
1324	    }
1325	
1326	  /* Extract data from netpkt.  If fragmented, copy out; else use pointer. */
1327	
1328	  if (netpkt_is_fragmented(pkt))
1329	    {
1330	      netpkt_copyout(dev, tmp_buf, pkt, len, 0);
1331	      data = tmp_buf;
1332	    }
1333	  else
1334	    {
1335	      data = netpkt_getdata(dev, pkt);
1336	      if (!data)
1337	        {
1338	          nerr("ERROR: netpkt_getdata returned NULL\n");
1339	          netpkt_free(dev, pkt, NETPKT_TX);
1340	          return -EINVAL;
1341	        }
1342	    }
1343	
1344	  /* Send via DMA */
1345	
1346	  ret = hw_transmit(priv, data, len);
1347	  if (ret < 0)
1348	    {
1349	      nerr("ERROR: hw_transmit failed: %d\n", ret);
1350	      netpkt_free(dev, pkt, NETPKT_TX);
1351	      return ret;
1352	    }
1353	
1354	  /* Track this packet: store it so tx_cleanup can free it after DMA done.
1355	   * The tx_cur was already advanced by hw_transmit, so use (tx_cur - 1).
1356	   */
1357	
1358	  {
1359	    irqstate_t flags = up_irq_save();
1360	    unsigned int slot = (priv->tx_cur - 1) & (TX_RING_SIZE - 1);
1361	
1362	    priv->tx_pkt[slot] = pkt;
1363	    up_irq_restore(flags);
1364	  }
1365	
1366	  return OK;
1367	}
