1369	/****************************************************************************
1370	 * Name: netdriver_receive
1371	 *
1372	 * Description:
1373	 *   OpenVela netdev_ops_s receive callback.  Called by upper half when
1374	 *   netdev_lower_rxready() was signaled.  Returns one received packet, or
1375	 *   NULL if no more packets are available.
1376	 *
1377	 *   Returned Value:
1378	 *     A netpkt_t * containing the received packet, or NULL.
1379	 *
1380	 ****************************************************************************/
1381	
1382	static FAR netpkt_t *netdriver_receive(FAR struct netdev_lowerhalf_s *dev)
1383	{
1384	  FAR struct sg2000_eth_priv_s *priv =
1385	      (FAR struct sg2000_eth_priv_s *)dev;
1386	  FAR netpkt_t *pkt = NULL;
1387	  struct sg2000_dma_desc_s *desc;
1388	  uint32_t status;
1389	  int frame_len;
1390	  int ret;
1391	
1392	  /* Check if there is a completed RX descriptor.
1393	   * Invalidate the descriptor cache line first so we read the status
1394	   * that DMA wrote back (OWN bit, frame length), not stale cached data.
1395	   */
1396	
1397	  desc = &priv->rx_desc[priv->rx_cur];
1398	  dcache_invalidate_range((uintptr_t)desc,
1399	                          (uintptr_t)desc +
1400	                          sizeof(struct sg2000_dma_desc_s));
1401	
1402	  if (desc->des0 & DESC_OWN)
1403	    {
1404	      /* DMA still owns it, no packet ready yet.
1405	       * This can happen if rxready was signaled for a previous packet
1406	       * that was already consumed, or in edge cases.
1407	       */
1408	
1409	      return NULL;
1410	    }
1411	
1412	  status = desc->des0;
1413	
1414	  /* Check for errors */
1415	
1416	  if (status & RX_DESC_ES)
1417	    {
1418	      nerr("ERROR: RX error, status=0x%08" PRIX32 "\n", status);
1419	      goto refill;
1420	    }
1421	
1422	  /* Get frame length (includes FCS which we strip) */
1423	
1424	  frame_len = ((status >> RX_DESC_FL_SHIFT) & RX_DESC_FL_MASK) - ETH_FCSSLEN;
1425	
1426	  if (frame_len <= 0 || frame_len > CONFIG_NET_ETH_PKTSIZE)
1427	    {
1428	      nwarn("WARNING: Invalid RX frame length: %d\n", frame_len);
1429	      goto refill;
1430	    }
1431	
1432	  /* Invalidate the RX data buffer so we read the data that DMA wrote,
1433	   * not stale cached data from a previous use of this buffer.
1434	   */
1435	
1436	  dcache_invalidate_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1437	                          (uintptr_t)priv->rx_buf[priv->rx_cur] +
1438	                          RX_BUF_SIZE);
1439	
1440	  /* Allocate a netpkt for the received data */
1441	
1442	  pkt = netpkt_alloc(dev, NETPKT_RX);
1443	  if (!pkt)
1444	    {
1445	      nerr("ERROR: netpkt_alloc failed\n");
1446	      goto refill;
1447	    }
1448	
1449	  /* Copy data from DMA RX buffer into the netpkt */
1450	
1451	  ret = netpkt_copyin(dev, pkt, priv->rx_buf[priv->rx_cur], frame_len, 0);
1452	  if (ret < 0)
1453	    {
1454	      nerr("ERROR: netpkt_copyin failed: %d\n", ret);
1455	      netpkt_free(dev, pkt, NETPKT_RX);
1456	      goto refill;
1457	    }
1458	
1459	  ninfo("RX packet: %d bytes\n", frame_len);
1460	
1461	refill:
1462	  /* Return the descriptor to DMA (set OWN=1).
1463	   * Re-set the buffer address in des2 in case DMA overwrote it,
1464	   * and flush the buffer to ensure clean state before DMA writes.
1465	   * Preserve RER (End of Ring) bit for the last descriptor.
1466	   */
1467	
1468	  desc->des0 = DESC_OWN |
1469	               ((priv->rx_cur == (RX_RING_SIZE - 1)) ? RX_DESC_RER : 0);
1470	  desc->des1 = RX_BUF_SIZE;
1471	  desc->des2 = (uint32_t)(uintptr_t)priv->rx_buf[priv->rx_cur];
1472	
1473	  /* Flush the RX buffer before handing it back to DMA:
1474	   * write back + invalidate so the buffer is clean for DMA to write into.
1475	   */
1476	
1477	  dcache_flush_range((uintptr_t)priv->rx_buf[priv->rx_cur],
1478	                     (uintptr_t)priv->rx_buf[priv->rx_cur] + RX_BUF_SIZE);
1479	
1480	  /* Write back the descriptor so DMA sees OWN=1 and the new buffer */
1481	
1482	  dcache_clean_range((uintptr_t)desc,
1483	                     (uintptr_t)desc + sizeof(struct sg2000_dma_desc_s));
1484	
1485	  priv->rx_cur = (priv->rx_cur + 1) & (RX_RING_SIZE - 1);
1486	  rx_doorbell(priv);
1487	
1488	  return pkt;
1489	}
