1513	/****************************************************************************
1514	 * Name: sg2000_eth_initialize
1515	 *
1516	 * Description:
1517	 *   Initialize the SG2000 Ethernet driver and register it with the OpenVela
1518	 *   network stack as a netdev_lowerhalf_s device.
1519	 *
1520	 *   Called from board_late_initialize() during system bringup.
1521	 *
1522	 ****************************************************************************/
1523	
1524	int sg2000_eth_initialize(void)
1525	{
1526	  FAR struct sg2000_eth_priv_s *priv = &g_eth_priv;
1527	  FAR struct netdev_lowerhalf_s *dev = &priv->dev;
1528	  int ret;
1529	
1530	  if (g_eth_initialized)
1531	    {
1532	      ninfo("SG2000 Ethernet driver already initialized\n");
1533	      return OK;
1534	    }
1535	
1536	  memset(priv, 0, sizeof(*priv));
1537	  priv->gmac_base = SG2000_GMAC_BASE;
1538	  priv->phy_base = SG2000_EPHY_BASE;
1539	  priv->phy_top = SG2000_EPHY_TOP;
1540	
1541	  /* Set a test MAC address (should be replaced with eFuse/OTP value) */
1542	
1543	  priv->mac_addr[0] = 0x02;
1544	  priv->mac_addr[1] = 0x00;
1545	  priv->mac_addr[2] = 0x00;
1546	  priv->mac_addr[3] = 0x00;
1547	  priv->mac_addr[4] = 0x00;
1548	  priv->mac_addr[5] = 0x01;
1549	
1550	  memcpy(dev->netdev.d_mac.ether.ether_addr_octet, priv->mac_addr,
1551	         IFHWADDRLEN);
1552	
1553	  dev->quota[NETPKT_TX] = TX_RING_SIZE / 2;
1554	  dev->quota[NETPKT_RX] = RX_RING_SIZE / 2;
1555	  dev->ops              = &g_ops;
1556	
1557	  priv->irq = SG2000_IRQ_GMAC;
1558	
1559	  ret = netdev_lower_register(dev, NET_LL_ETHERNET);
1560	  if (ret < 0)
1561	    {
1562	      nerr("ERROR: netdev_lower_register failed: %d\n", ret);
1563	      return ret;
1564	    }
1565	
1566	  netdev_lower_carrier_off(dev);
1567	  g_eth_initialized = true;
1568	  ninfo("SG2000 Ethernet driver registered as eth0 (lowerhalf)\n");
1569	
1570	  gmac_clock_enable();
1571	
1572	  ret = irq_attach(priv->irq, sg2000_eth_isr, priv);
1573	  if (ret < 0)
1574	    {
1575	      nerr("ERROR: irq_attach failed: %d\n", ret);
1576	      return OK;
1577	    }
1578	
1579	  up_enable_irq(priv->irq);
1580	  ninfo("IRQ %d enabled\n", priv->irq);
1581	
1582	  return OK;
1583	}
